#include <bits/stdc++.h>
using namespace std;

int aCount, bCount, totalN, maxK;
const long long MOD = 1000000007;
long long chooseArr[100][100];
struct Pair {
    int depth;
    long long ways;
    Pair(int d, long long w) : depth(d), ways(w) {}
};
unordered_map<int, Pair> stateMap;
queue<int> stateQueue;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> totalN >> maxK;
    aCount = 0;
    bCount = 0;
    for (int i = 0; i < totalN; i++) {
        int val; cin >> val;
        if (val == 50) aCount++;
        else bCount++;
    }
    // Generate chooseArr
    for (int i = 0; i < 100; i++) chooseArr[i][0] = 1;
    for (int i = 1; i < 100; i++) {
        for (int j = 1; j <= i; j++) {
            chooseArr[i][j] = (chooseArr[i - 1][j - 1] + chooseArr[i - 1][j]) % MOD;
        }
    }
    int startState = 1000000 + 100 * aCount + bCount;
    stateQueue.push(startState);
    stateMap[startState] = Pair(0, 1);
    while (!stateQueue.empty()) {
        int state = stateQueue.front();
        stateQueue.pop();
        int side = state / 1000000;
        int nA = (state % 1000000) / 100;
        int nB = state % 100;
        if (side > 0) {
            for (int i = nA; i >= 0 && 50 * (nA - i) <= maxK; i--) {
                for (int j = nB; j >= 0 && 50 * (nA - i) + 100 * (nB - j) <= maxK; j--) {
                    if (i != nA || j != nB) {
                        long long ways = (chooseArr[nA][i] * chooseArr[nB][j]) % MOD;
                        int newState = 1000000 * (1 - side) + i * 100 + j;
                        int newDepth = stateMap[state].depth + 1;
                        if (stateMap.find(newState) == stateMap.end()) {
                            stateMap[newState] = Pair(newDepth, 0);
                            stateQueue.push(newState);
                        }
                        if (stateMap[newState].depth == newDepth) {
                            stateMap[newState].ways = (stateMap[newState].ways + stateMap[state].ways * ways % MOD) % MOD;
                        }
                    }
                }
            }
        } else {
            for (int i = nA; i <= aCount && 50 * (i - nA) <= maxK; i++) {
                for (int j = nB; j <= bCount && 50 * (i - nA) + 100 * (j - nB) <= maxK; j++) {
                    if (i != nA || j != nB) {
                        long long ways = (chooseArr[aCount - nA][i - nA] * chooseArr[bCount - nB][j - nB]) % MOD;
                        int newState = 1000000 * (1 - side) + i * 100 + j;
                        int newDepth = stateMap[state].depth + 1;
                        if (stateMap.find(newState) == stateMap.end()) {
                            stateMap[newState] = Pair(newDepth, 0);
                            stateQueue.push(newState);
                        }
                        if (stateMap[newState].depth == newDepth) {
                            stateMap[newState].ways = (stateMap[newState].ways + stateMap[state].ways * ways % MOD) % MOD;
                        }
                    }
                }
            }
        }
    }
    if (stateMap.find(0) != stateMap.end()) {
        cout << stateMap[0].depth << "\n" << stateMap[0].ways << "\n";
    } else {
        cout << -1 << "\n0\n";
    }
    return 0;
}

